package com.rustypayments.legacy;

import com.rustypayments.PaymentCalendar;
import java.time.*;
import java.time.format.*;
import java.time.temporal.ChronoUnit;

public class LegacyPaymentCalendar implements PaymentCalendar {
    private static final ZoneId WARSAW = ZoneId.of("Europe/Warsaw");
    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);
    private static final DateTimeFormatter INSTANT_FORMATTER = DateTimeFormatter.ofPattern("uuuu-MM-dd'T'HH:mm:ssXXX")
            .withResolverStyle(ResolverStyle.STRICT);

    @Override
    public boolean isBusinessDay(String date) {
        return isBusinessDay(parseDate(date));
    }

    private LocalDate parseDate(String date) {
        if (date == null) throw new IllegalArgumentException("Date cannot be null");
        try {
            return LocalDate.parse(date, DATE_FORMATTER);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid date format or value: " + date);
        }
    }

    private OffsetDateTime parseInstant(String instant) {
        if (instant == null) throw new IllegalArgumentException("Instant cannot be null");
        try {
            return OffsetDateTime.parse(instant, INSTANT_FORMATTER);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid instant format: " + instant);
        }
    }

    private boolean isBusinessDay(LocalDate d) {
        DayOfWeek dow = d.getDayOfWeek();
        if (dow == DayOfWeek.SATURDAY || dow == DayOfWeek.SUNDAY) return false;
        int m = d.getMonthValue();
        int day = d.getDayOfMonth();
        if (m == 1 && day == 1) return false;   // New Year
        if (m == 1 && day == 6) return false;   // Epiphany
        if (m == 5 && day == 1) return false;   // Labour Day
        if (m == 5 && day == 3) return false;   // Constitution Day
        if (m == 8 && day == 15) return false;  // Assumption
        if (m == 11 && day == 1) return false;  // All Saints
        if (m == 11 && day == 11) return false; // Independence Day
        if (m == 12 && day == 25) return false; // Christmas
        if (m == 12 && day == 26) return false; // Boxing Day
        return true;
    }

    @Override
    public String processingDate(String submittedAt) {
        ZonedDateTime zdt = parseInstant(submittedAt).atZoneSameInstant(WARSAW);
        LocalDate d = zdt.toLocalDate();
        LocalTime t = zdt.toLocalTime();

        if (isBusinessDay(d) && !t.isAfter(LocalTime.of(16, 0, 0))) {
            return d.format(DATE_FORMATTER);
        }
        return nextBusinessDay(d).format(DATE_FORMATTER);
    }

    @Override
    public String settlementDate(String submittedAt) {
        LocalDate proc = parseDate(processingDate(submittedAt));
        return nextBusinessDay(proc).format(DATE_FORMATTER);
    }

    private LocalDate nextBusinessDay(LocalDate d) {
        LocalDate next = d.plusDays(1);
        while (!isBusinessDay(next)) {
            next = next.plusDays(1);
        }
        return next;
    }

    @Override
    public int daysLate(String dueDate, String paidAt) {
        LocalDate due = parseDate(dueDate);
        LocalDate paid = parseInstant(paidAt).atZoneSameInstant(WARSAW).toLocalDate();
        long days = ChronoUnit.DAYS.between(due, paid);
        return (int) Math.max(0, days);
    }

    @Override
    public String addMonths(String date, int months) {
        LocalDate d = parseDate(date);
        boolean wasLastDay = d.getDayOfMonth() == d.lengthOfMonth();
        LocalDate result = d.plusMonths(months);
        if (wasLastDay) {
            result = result.withDayOfMonth(result.lengthOfMonth());
        }
        return result.format(DATE_FORMATTER);
    }
}

